(S, "Golan Heights are occupied by which country?", ["Israel", "Jordan", "Lebanon", "Egypt"], 0, "Israel captured the Golan Heights from Syria in the 1967 war and later annexed it.", "The Golan Heights are internationally recognised as Syrian territory.", [2059]),
(S, "According to the Quran, who will be in the lowest depths of the Fire?", ["The hypocrites (Munafiqeen)", "The thieves", "The liars", "The proud"], 0, "Surah An-Nisa says the hypocrites will be in the lowest depths of the Fire.", "Hypocrites outwardly claimed faith while hiding disbelief.", [1692]),
